('address', 'address', '/əˈdrɛs/', 'verb', 'the details of where a person lives or works', 'She wrote her address on the back of the envelope.', 'to deal with or confront a problem directly', 'The committee met for three hours to address the shortage of affordable housing.', ARRAY['location','residence']::text[], ARRAY['anonymity']::text[], 'Medium', 88, 'Multiple Meanings', 1, ARRAY['multi-meaning']::text[], 'multiple-meaning set'),
('appreciate', 'appreciate', '/əˈpriʃieɪt/', 'verb', 'to value something or feel grateful for it', 'We appreciate the extra hours you spent on the report.', 'to increase in value over time', 'The painting has appreciated considerably since it was purchased forty years ago.', ARRAY['value','esteem']::text[], ARRAY['disparage']::text[], 'Hard', 89, 'Multiple Meanings', 1, ARRAY['multi-meaning']::text[], 'multiple-meaning set'),
('arrest', 'arrest', '/əˈrɛst/', 'verb', 'to seize a person by legal authority', 'Officers arrested two suspects near the warehouse.', 'to stop or slow the progress of something', 'Cold weather arrested the growth of the seedlings for several weeks.', ARRAY['detain','apprehend']::text[], ARRAY['release']::text[], 'Hard', 87, 'Multiple Meanings', 1, ARRAY['multi-meaning']::text[], 'multiple-meaning set'),
('bearing', 'bearing', '/ˈbɛrɪŋ/', 'noun', 'the way a person stands, moves, or behaves', 'His calm bearing reassured the passengers during the delay.', 'relevance or influence on a matter', 'Her early research has a direct bearing on how the results are now interpreted.', ARRAY['demeanor','manner']::text[], ARRAY['agitation']::text[], 'Hard', 88, 'Multiple Meanings', 1, ARRAY['multi-meaning']::text[], 'multiple-meaning set'),
('capacity', 'capacity', '/kəˈpæsɪti/', 'noun', 'the greatest amount something can hold or produce', 'The stadium has a capacity of sixty thousand.', 'a role or position in which someone acts', 'He signed the agreement in his capacity as director of the foundation.', ARRAY['volume','limit']::text[], ARRAY['shortfall']::text[], 'Hard', 90, 'Multiple Meanings', 1, ARRAY['core-academic','multi-meaning']::text[], 'multiple-meaning set'),
