('coin', 'coin', '/kɔɪn/', 'verb', 'a flat piece of metal used as money', 'He found an old coin buried near the wall.', 'to invent a new word or phrase', 'The novelist coined a word for the feeling that no existing term captured.', ARRAY['token','currency']::text[], ARRAY[]::text[], 'Hard', 85, 'Multiple Meanings', 1, ARRAY['multi-meaning']::text[], 'multiple-meaning set'),
