('harbor', 'harbor', '/ˈhɑrbər/', 'verb', 'a sheltered stretch of water where ships anchor', 'Fishing boats returned to the harbor before dark.', 'to hold a thought or feeling privately over time', 'He harbored resentment about the decision for years without mentioning it.', ARRAY['port','haven']::text[], ARRAY[]::text[], 'Hard', 87, 'Multiple Meanings', 1, ARRAY['multi-meaning']::text[], 'multiple-meaning set'),
