('project', 'project', '/prəˈdʒɛkt/', 'verb', 'a planned piece of work with a defined goal', 'The project will take eighteen months to complete.', 'to estimate or forecast a future figure', 'The agency projects a modest rise in population over the next twenty years.', ARRAY['undertaking','venture']::text[], ARRAY[]::text[], 'Hard', 88, 'Multiple Meanings', 1, ARRAY['multi-meaning']::text[], 'multiple-meaning set'),
('qualify', 'qualify', '/ˈkwɑlɪfaɪ/', 'verb', 'to meet the standard required for something', 'She qualified for the final with her second jump.', 'to limit or soften a statement so it is less absolute', 'He qualified his praise by adding that the study covered only one region.', ARRAY['certify','entitle']::text[], ARRAY['disqualify']::text[], 'Hard', 93, 'Multiple Meanings', 1, ARRAY['multi-meaning']::text[], 'multiple-meaning set'),
('reservation', 'reservation', '/ˌrɛzərˈveɪʃən/', 'noun', 'an arrangement to hold a seat, room, or table', 'We made a reservation for seven at the restaurant.', 'a doubt that prevents full agreement', 'She supported the plan without reservation once the safeguards were added.', ARRAY['booking','arrangement']::text[], ARRAY[]::text[], 'Hard', 89, 'Multiple Meanings', 1, ARRAY['multi-meaning']::text[], 'multiple-meaning set'),
('reserve', 'reserve', '/rɪˈzɜrv/', 'noun', 'a supply kept back for later use', 'The country holds a large reserve of grain.', 'restraint in showing feelings or opinions', 'She spoke with a reserve that made her rare enthusiasm memorable.', ARRAY['stockpile','store']::text[], ARRAY[]::text[], 'Hard', 86, 'Multiple Meanings', 1, ARRAY['multi-meaning']::text[], 'multiple-meaning set'),
