on conflict (id) do update set
  word = excluded.word, pronunciation = excluded.pronunciation,
  part_of_speech = excluded.part_of_speech, definition = excluded.definition,
  example = excluded.example, alt_definition = excluded.alt_definition,
  alt_example = excluded.alt_example, synonyms = excluded.synonyms,
  antonyms = excluded.antonyms, difficulty = excluded.difficulty,
  priority = excluded.priority, category = excluded.category,
  tier = excluded.tier, groups = excluded.groups, source = excluded.source;

-- authored context items; other forms are generated at runtime from the word
delete from items where form = 'context';
insert into items (word_id, form, prompt, choices, answer, explanation) values
('abate', 'context', 'After several hours, the winds began to _____, allowing crews to work safely.', ARRAY['abate','accelerate','consolidate','provoke']::text[], 'abate', 'The sentence describes the winds becoming less intense, so abate is precise.'),
('ambiguous', 'context', 'Because the instructions were _____, students were unsure what the teacher expected.', ARRAY['ambiguous','meticulous','conspicuous','conventional']::text[], 'ambiguous', 'Ambiguous means unclear because it allows multiple interpretations.'),
('arbitrary', 'context', 'The committee wanted a consistent policy, not an _____ rule that changed from case to case.', ARRAY['arbitrary','empirical','coherent','integral']::text[], 'arbitrary', 'An arbitrary rule lacks a consistent rational basis.'),
('corroborate', 'context', 'The witness statement was useful, but investigators needed records to _____ it.', ARRAY['corroborate','mitigate','deter','reconcile']::text[], 'corroborate', 'Corroborate means to confirm or strengthen a claim with evidence.'),
('diminish', 'context', 'The thick curtains helped _____ the amount of sunlight entering the room.', ARRAY['diminish','exacerbate','elicit','facilitate']::text[], 'diminish', 'The curtains reduced the amount of sunlight.'),
('elicit', 'context', 'The interviewer asked an open-ended question to _____ detailed responses from participants.', ARRAY['elicit','inhibit','contradict','deter']::text[], 'elicit', 'Elicit means to draw something out, such as a response or information.'),
('empirical', 'context', 'The researchers supported their conclusion with _____ data collected from repeated trials.', ARRAY['empirical','arbitrary','ambiguous','sporadic']::text[], 'empirical', 'Empirical evidence comes from observation or experiment.'),
('equivocal', 'context', 'The mayor gave an _____ response, avoiding a clear yes or no.', ARRAY['equivocal','explicit','meticulous','fundamental']::text[], 'equivocal', 'An equivocal response is deliberately unclear or open to interpretation.'),
('exacerbate', 'context', 'Adding more restrictions could _____ the shortage rather than solve it.', ARRAY['exacerbate','mitigate','corroborate','reconcile']::text[], 'exacerbate', 'To exacerbate a problem is to make it worse.'),
('facilitate', 'context', 'The online form was designed to _____ the application process.', ARRAY['facilitate','impede','undermine','contradict']::text[], 'facilitate', 'Facilitate means to make a process easier.'),
('inhibit', 'context', 'Excessive noise can _____ a student''s ability to concentrate.', ARRAY['inhibit','elicit','facilitate','substantiate']::text[], 'inhibit', 'Inhibit means to prevent or restrain a process or behavior.'),
('inherent', 'context', 'The researchers recognized that some uncertainty was _____ in the measurement process.', ARRAY['inherent','arbitrary','sporadic','subsequent']::text[], 'inherent', 'Inherent means naturally present as part of something.'),
('mitigate', 'context', 'The city planted trees to _____ the effects of extreme summer heat.', ARRAY['mitigate','exacerbate','elicit','contradict']::text[], 'mitigate', 'Mitigate means to make a harmful or severe effect less serious.'),
('novel', 'context', 'The researchers developed a _____ technique that differed from established methods.', ARRAY['novel','conventional','arbitrary','sporadic']::text[], 'novel', 'Here novel means new or original.'),
('pragmatic', 'context', 'Rather than debate every theoretical possibility, the manager took a _____ approach focused on what would work.', ARRAY['pragmatic','arbitrary','equivocal','conspicuous']::text[], 'pragmatic', 'Pragmatic describes a practical, results-focused approach.'),
('profound', 'context', 'The discovery had a _____ effect on how scientists understood the disease.', ARRAY['profound','sporadic','discrete','tentative']::text[], 'profound', 'The effect was described as very significant and far-reaching.'),
('reconcile', 'context', 'Researchers had to _____ two results that initially seemed inconsistent.', ARRAY['reconcile','elicit','diminish','facilitate']::text[], 'reconcile', 'To reconcile is to make apparently conflicting information fit together.'),
('subsequent', 'context', 'The initial study was promising, but _____ experiments produced different results.', ARRAY['subsequent','inherent','arbitrary','conspicuous']::text[], 'subsequent', 'Subsequent means occurring later or after something else.'),
('substantiate', 'context', 'The scientist needed additional trials to _____ the surprising claim.', ARRAY['substantiate','mitigate','deter','abate']::text[], 'substantiate', 'Substantiate means to support a claim with evidence.'),
('transcend', 'context', 'The artist''s work seemed to _____ the boundaries between science and art.', ARRAY['transcend','inhibit','diminish','contradict']::text[], 'transcend', 'To transcend a boundary is to go beyond it.'),
('viable', 'context', 'The proposal would be a _____ option only if its costs could be reduced.', ARRAY['viable','ambiguous','sporadic','conspicuous']::text[], 'viable', 'Viable means capable of working successfully.'),
('advocate', 'context', 'The researchers _____ using local data instead of a national average.', ARRAY['advocate','contradict','inhibit','deter']::text[], 'advocate', 'As a verb, advocate means to publicly support an idea or course of action.'),
('conventional', 'context', 'The team chose a _____ method because it had been widely tested.', ARRAY['conventional','novel','arbitrary','equivocal']::text[], 'conventional', 'Conventional means traditional or commonly accepted.'),
('conspicuous', 'context', 'The bright orange marker was especially _____ against the white background.', ARRAY['conspicuous','discrete','inherent','tentative']::text[], 'conspicuous', 'The marker was easy to notice because of its contrast.'),
('discrete', 'context', 'The survey divided participants into three _____ groups for analysis.', ARRAY['discrete','profound','subsequent','arbitrary']::text[], 'discrete', 'Discrete means separate and distinct rather than continuous.'),
('integral', 'context', 'Reliable data are _____ to the study''s conclusions; without them, the analysis would fail.', ARRAY['integral','sporadic','tentative','ambiguous']::text[], 'integral', 'Integral means necessary to the completeness or function of something.'),
('inconsistent', 'context', 'The results were _____ with the theory, so researchers investigated further.', ARRAY['inconsistent','integral','novel','explicit']::text[], 'inconsistent', 'Inconsistent means not matching or not agreeing.'),
('meticulous', 'context', 'The lab assistant was _____ about labeling every sample correctly.', ARRAY['meticulous','arbitrary','sporadic','equivocal']::text[], 'meticulous', 'Meticulous means extremely careful and precise.'),
('predominant', 'context', 'The _____ view among researchers was that more data were needed.', ARRAY['predominant','tentative','discrete','ambiguous']::text[], 'predominant', 'The predominant view was the most widely held or influential.'),
